#include <stdio.h>
#include <string.h>

int main(void) {
    FILE *f = fopen("log.txt", "r");
    if (f == NULL) {
        perror("log.txt");
        return 1;
    }
    char line[256];
    int info = 0, warn = 0, error = 0;
    while (fgets(line, sizeof line, f) != NULL) {
        if (strncmp(line, "INFO ", 5) == 0) info++;
        else if (strncmp(line, "WARN ", 5) == 0) warn++;
        else if (strncmp(line, "ERROR ", 6) == 0) error++;
    }
    fclose(f);
    printf("INFO %d\nWARN %d\nERROR %d\n", info, warn, error);
    return 0;
}
